<template><main class="ops-page"><div class="ops-heading"><div><div class="ops-eyebrow">{{ platform?'平台运营 / 订单监管':'交易中心 / 订单管理' }}</div><h1>{{ platform?'订单监管':'订单管理' }}</h1><p>{{ platform?'查询全平台订单与售后进度，退款由所属主办方审核。':'查询本机构订单，核对票券并处理退款申请。' }}</p></div><div class="ops-actions"><button @click="load" :disabled="loading"><AppIcon name="refresh" size="15"/>刷新数据</button></div></div>
 <section class="ops-panel"><div class="order-filters"><label>搜索订单<input v-model.trim="keyword" placeholder="订单号、ID或活动名称" /></label><label>活动<select v-model="activityId" @change="sessionId='' "><option value="">全部活动</option><option v-for="a in activities" :key="a.id" :value="a.id">{{ a.title }}</option></select></label><label v-if="platform">主办方<select v-model="organizerId"><option value="">全部主办方</option><option v-for="o in organizations" :key="o.id" :value="o.id">{{ o.name }}</option></select></label><label>场次<select v-model="sessionId"><option value="">全部场次</option><option v-for="s in sessions" :key="s.id" :value="s.id">{{ format(s.start) }}</option></select></label><label>订单状态<select v-model="status"><option value="">全部状态</option><option v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</option></select></label><label>下单起始日期<ChineseDateTimeInput type="date" v-model="start"/></label><label>下单截止日期<ChineseDateTimeInput type="date" v-model="end"/></label><button @click="reset">重置筛选</button></div><p v-if="route.query.paidToday||route.query.paymentDays||route.query.refundDays" class="order-hint">{{ route.query.paidToday?'当前显示今日支付的订单':route.query.refundDays?'当前按退款完成日期筛选':'当前按支付日期筛选' }}；{{ route.query.paidToday?'今日':`近 ${route.query.paymentDays||route.query.refundDays} 日` }}（北京时间）。</p></section>
 <section class="ops-panel order-table-wrap"><p v-if="loading" class="ops-empty">订单加载中…</p><p v-else-if="error" class="ops-error" role="alert">{{ error }} <button @click="load">重试</button></p><p v-else-if="start&&end&&start>end" class="ops-error">截止日期不能早于起始日期</p><p v-else-if="!filtered.length" class="ops-empty">暂无符合条件的订单</p><table v-else class="ops-orders"><thead><tr><th>订单</th><th>活动与票种</th><th>实名观众</th><th>数量</th><th class="number">实付金额</th><th>支付 / 售后状态</th><th>下单时间</th><th>操作</th></tr></thead><tbody><tr v-for="o in paged" :key="o.orderId"><td><b>{{ o.orderNo||o.orderId }}</b><small>ID：{{ o.orderId }}</small></td><td><div class="order-activity"><ActivityCover :src="o.coverFileUrl||''" :title="o.activityTitle||''"/><div><b>{{ o.activityTitle||'活动资料不可用' }}</b><small>{{ o.ticketTypeName }} × {{ o.quantity }}</small><small>{{ format(o.sessionStartTime) }}</small></div></div></td><td>{{ o.realName||'未提供' }}<small>账号 ID：{{ o.userId||'—' }}</small></td><td>{{ o.quantity }}</td><td class="number order-money">¥{{ Number(o.payAmount??o.amount??0).toFixed(2) }}</td><td><span class="order-status" :class="'status-'+o.status">{{ labels[o.status]||o.status }}</span><small v-if="o.latestRefund?.status==='REJECTED'">退票申请未通过</small></td><td>{{ format(o.createdAt) }}</td><td><RouterLink :to="{path:base+'/orders/'+o.orderId,query:{...route.query}}">{{ !platform&&o.status==='REFUNDING'?'审核退款':'查看详情' }}</RouterLink><RouterLink v-if="o.activityId" :to="{path:base+'/verification',query:{activityId:o.activityId,sessionId:o.sessionId,orderId:o.orderId}}">核销记录</RouterLink></td></tr></tbody></table><div class="order-pagination"><span>共 {{ filtered.length }} 笔，第 {{ page }} 页</span><div><button :disabled="page===1" @click="page--">上一页</button><button :disabled="page*20>=filtered.length" @click="page++">下一页</button></div></div></section>
</main></template>
<script setup>
import ChineseDateTimeInput from './ChineseDateTimeInput.vue'
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {platformOrderApi} from '../api/platformOrder'
import {organizerOrderApi} from '../api/organizerOrder'
import ActivityCover from './ActivityCover.vue'
import AppIcon from './AppIcon.vue'
const props=defineProps({platform:Boolean}),route=useRoute(),router=useRouter(),rows=ref([]),loading=ref(true),error=ref('')
const organizerId=ref(''),keyword=ref(''),status=ref(''),activityId=ref(''),sessionId=ref(''),start=ref(''),end=ref(''),page=ref(1)
const base=computed(()=>`/management/${props.platform?'platform':'organizer'}`)
const labels={PENDING_PAYMENT:'待支付',PAID:'已支付',REFUNDING:'退款待审核',REFUNDED:'已退款',CANCELLED:'已取消',EXPIRED:'已过期',COMPLETED:'已完成'}
const format=v=>v?String(v).replace('T',' ').slice(0,16):'—'
const activities=computed(()=>[...new Map(rows.value.filter(o=>o.activityId).map(o=>[String(o.activityId),{id:String(o.activityId),title:o.activityTitle}])).values()])
const organizations=computed(()=>[...new Map(rows.value.filter(o=>o.organizerId).map(o=>[String(o.organizerId),{id:String(o.organizerId),name:o.organizerName||String(o.organizerId)}])).values()])
const sessions=computed(()=>[...new Map(rows.value.filter(o=>o.sessionId&&(!activityId.value||String(o.activityId)===activityId.value)).map(o=>[String(o.sessionId),{id:String(o.sessionId),start:o.sessionStartTime}])).values()])
function periodDate(v){return v?String(v).slice(0,10):''}
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
function inDays(value,n){if(!value)return false;const date=periodDate(value),to=today(),d=new Date(to+'T00:00:00+08:00');d.setUTCDate(d.getUTCDate()-(Number(n)-1));const from=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);return date>=from&&date<=to}
const filtered=computed(()=>rows.value.filter(o=>(!organizerId.value||String(o.organizerId)===organizerId.value)&&(!status.value||o.status===status.value)&&(!activityId.value||String(o.activityId)===activityId.value)&&(!sessionId.value||String(o.sessionId)===sessionId.value)&&(!keyword.value||[o.orderId,o.orderNo,o.activityTitle].some(v=>String(v||'').toLowerCase().includes(keyword.value.toLowerCase())))&&(!start.value||periodDate(o.createdAt)>=start.value)&&(!end.value||periodDate(o.createdAt)<=end.value)&&(!route.query.paidToday||periodDate(o.paidAt)===today())&&(!route.query.paymentDays||inDays(o.paidAt,route.query.paymentDays))&&(!route.query.refundDays||o.latestRefund?.status==='REFUNDED'&&inDays(o.latestRefund.processedAt,route.query.refundDays))))
const paged=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20))
watch(()=>route.query,q=>{organizerId.value=String(q.organizerId||'');keyword.value=String(q.keyword||'');status.value=String(q.status||'');activityId.value=String(q.activityId||'');sessionId.value=String(q.sessionId||'');start.value=String(q.start||'');end.value=String(q.end||'');page.value=Math.max(1,Number(q.page)||1)},{immediate:true})
watch([organizerId,keyword,status,activityId,sessionId,start,end],()=>{page.value=1})
watch([organizerId,keyword,status,activityId,sessionId,start,end,page],()=>router.replace({query:{...route.query,organizerId:organizerId.value||undefined,keyword:keyword.value||undefined,status:status.value||undefined,activityId:activityId.value||undefined,sessionId:sessionId.value||undefined,start:start.value||undefined,end:end.value||undefined,page:page.value>1?page.value:undefined}}))
function reset(){router.replace({query:{}})}
let request=0
async function load(){const current=++request;loading.value=true;error.value='';try{const result=await(props.platform?platformOrderApi:organizerOrderApi).list('');if(current===request)rows.value=Array.isArray(result)?result:[]}catch(e){if(current===request)error.value=e.message||'订单加载失败'}finally{if(current===request)loading.value=false}}
load()
</script>
<style scoped>
.order-filters{display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap}.order-filters label{display:flex;flex-direction:column;gap:7px;font-size:12px;color:#7184a0}.order-filters input,.order-filters select{padding:9px 10px;border:1px solid #dce5f2;border-radius:8px;background:#fbfcff;color:#354f70;max-width:215px;font-size:12px}.order-filters button,.order-pagination button{padding:10px 12px;border:1px solid #dce5f2;border-radius:8px;background:#f5f8ff;color:#2161e8;font-size:12px;cursor:pointer}.order-hint{font-size:12px;color:#6887b5;margin-top:16px}.order-table-wrap{overflow:auto}.ops-orders{width:100%;border-collapse:collapse;min-width:1080px}.ops-orders th,.ops-orders td{text-align:left;padding:15px 12px;border-bottom:1px solid #edf1f7;font-size:12px}.ops-orders th{background:#f6f9fd;color:#8091aa}.ops-orders small{display:block;color:#8797ad;font-size:11px;line-height:1.8;margin-top:4px}.ops-orders b{font-size:12px;overflow-wrap:anywhere}.ops-orders td:first-child{max-width:200px}.ops-orders .number{text-align:right;white-space:nowrap}.order-money{font-weight:700;color:#2161e8}.order-activity{display:flex;align-items:center;gap:12px;min-width:230px}.order-activity>.activity-cover{width:55px;height:70px;flex:none;border-radius:7px}.ops-orders td:last-child a{display:block;font-size:12px;color:#2161e8;white-space:nowrap;margin:8px 0}.order-status{display:inline-block;padding:5px 9px;border-radius:15px;background:#edf3ff;color:#326bdd;font-size:11px}.status-REFUNDING{color:#b67a21;background:#fff4df}.status-CANCELLED,.status-EXPIRED,.status-REFUNDED{color:#8290a6;background:#eff2f7}.order-pagination{display:flex;justify-content:space-between;align-items:center;font-size:12px;color:#8392a7;margin-top:20px}.order-pagination>div{display:flex;gap:8px}
</style>
